package io.github.hoangtnedu.java.orders;
import jakarta.persistence.*;import java.util.*;import java.math.BigDecimal;
public class CustomerService implements AutoCloseable {
 private final EntityManagerFactory emf=Persistence.createEntityManagerFactory("orders",Database.jpa());
 public long create(Database.User customer,long product,int quantity){if(!"CUSTOMER".equals(customer.role())||quantity<1)throw new IllegalArgumentException("Invalid customer/quantity");try(var em=emf.createEntityManager()){var tx=em.getTransaction();try{tx.begin();Object[] p=(Object[])em.createNativeQuery("SELECT price,stock FROM products WHERE id=?1").setParameter(1,product).getSingleResult();BigDecimal price=(BigDecimal)p[0];Order o=new Order();o.customerId=customer.id();o.createdAt=java.time.LocalDateTime.now();o.totalAmount=price.multiply(BigDecimal.valueOf(quantity));o.status="PENDING";em.persist(o);em.flush();em.createNativeQuery("INSERT INTO order_items(order_id,product_id,quantity,unit_price,subtotal) VALUES(?1,?2,?3,?4,?5)").setParameter(1,o.id).setParameter(2,product).setParameter(3,quantity).setParameter(4,price).setParameter(5,o.totalAmount).executeUpdate();em.createNativeQuery("INSERT INTO order_status_history(order_id,new_status,changed_by,platform) VALUES(?1,'PENDING',?2,'JAKARTA')").setParameter(1,o.id).setParameter(2,customer.id()).executeUpdate();tx.commit();return o.id;}catch(RuntimeException e){if(tx.isActive())tx.rollback();throw e;}}}
 public void complete(Database.User customer,long id){try(var em=emf.createEntityManager()){var tx=em.getTransaction();try{tx.begin();Order o=em.find(Order.class,id,LockModeType.PESSIMISTIC_WRITE);if(o==null||o.customerId!=customer.id()||!"CUSTOMER".equals(customer.role())||!"SHIPPING".equals(o.status))throw new IllegalArgumentException("Wrong owner/state");o.status="COMPLETED";em.createNativeQuery("INSERT INTO order_status_history(order_id,old_status,new_status,changed_by,platform) VALUES(?1,'SHIPPING','COMPLETED',?2,'JAKARTA')").setParameter(1,id).setParameter(2,customer.id()).executeUpdate();tx.commit();}catch(RuntimeException e){if(tx.isActive())tx.rollback();throw e;}}}
 public java.util.List<Order> list(long customer){try(var em=emf.createEntityManager()){return em.createQuery("select o from Order o where o.customerId=:id",Order.class).setParameter("id",customer).getResultList();}}
 public void close(){emf.close();}
}